/**
 * @file src/lib/evolutionItemTooltip.ts
 * Tooltip sac : Pokémon possédés compatibles avec un objet d'évolution.
 */

import { EVOLUTIONS, isEvolutionInventoryItem, resolveEvolutionConditionItem } from '../../constants/evolutions.ts';
import type { EvolutionDefinition, EvolutionOption } from '../../constants/evolutionTypes.ts';
import { coerceStr, coalesceStr } from './coerceStr.ts';
import { uiPokemonName, uiText } from '../ui/i18n.ts';
import type { CreatureData } from '../types/creature.js';
import type { GameRuntime } from '../types/game.js';
import { isEvolutionTargetUnlockedForProgress } from './evolutionRegionGate.ts';

export interface OwnedCompatibleEvolution {
    creatureName: string;
    evolvesTo: string;
    requiredLevel: number | null;
    levelMet: boolean;
}

function forEachOwnedCreature(game: GameRuntime, fn: (creature: CreatureData) => void): void {
    for (const list of [game.playerTeam, game.storage, game.pension]) {
        if (!Array.isArray(list)) continue;
        for (const creature of list) {
            if (creature) fn(creature);
        }
    }
}

function compatibleOptionsForCreature(
    game: GameRuntime,
    creature: CreatureData,
    itemKey: string,
): OwnedCompatibleEvolution[] {
    const evolutionData: EvolutionDefinition | undefined = EVOLUTIONS[creature.name];
    if (!evolutionData) return [];

    const matches: OwnedCompatibleEvolution[] = [];
    const pushIfMatching = (raw: EvolutionOption | EvolutionDefinition) => {
        const condItem = 'conditionItem' in raw ? raw.conditionItem : undefined;
        const condStr = coalesceStr(condItem, coerceStr(raw.condition));
        const requiredItem = resolveEvolutionConditionItem(condStr);
        if (requiredItem !== itemKey) return;

        const evolvesTo = raw.evolves_to ?? evolutionData.evolves_to;
        if (!evolvesTo) return;
        if (!isEvolutionTargetUnlockedForProgress(game, evolvesTo)) return;

        const requiredLevel = Number(raw.level != null ? raw.level : evolutionData.level);
        const levelMet = Number.isFinite(requiredLevel) ? creature.level >= requiredLevel : true;

        matches.push({
            creatureName: creature.name,
            evolvesTo,
            requiredLevel: Number.isFinite(requiredLevel) ? requiredLevel : null,
            levelMet,
        });
    };

    if (Array.isArray(evolutionData.options) && evolutionData.options.length > 0) {
        evolutionData.options.forEach(pushIfMatching);
        return matches;
    }

    pushIfMatching(evolutionData);
    return matches;
}

function dedupeCompatibleEvolutions(entries: OwnedCompatibleEvolution[]): OwnedCompatibleEvolution[] {
    const byKey = new Map<string, OwnedCompatibleEvolution>();
    for (const entry of entries) {
        const key = `${entry.creatureName}|${entry.evolvesTo}`;
        const existing = byKey.get(key);
        if (!existing) {
            byKey.set(key, entry);
            continue;
        }
        if (!existing.levelMet && entry.levelMet) {
            byKey.set(key, entry);
            continue;
        }
        if (existing.levelMet === entry.levelMet
            && entry.requiredLevel != null
            && (existing.requiredLevel == null || entry.requiredLevel < existing.requiredLevel)) {
            byKey.set(key, entry);
        }
    }
    return [...byKey.values()];
}

export function getOwnedCompatibleEvolutionsForItem(
    game: GameRuntime,
    itemKey: string,
): OwnedCompatibleEvolution[] {
    if (!isEvolutionInventoryItem(itemKey)) return [];

    const collected: OwnedCompatibleEvolution[] = [];
    forEachOwnedCreature(game, (creature) => {
        collected.push(...compatibleOptionsForCreature(game, creature, itemKey));
    });

    return dedupeCompatibleEvolutions(collected).sort((a, b) => {
        const nameA = uiPokemonName(game, a.creatureName);
        const nameB = uiPokemonName(game, b.creatureName);
        return nameA.localeCompare(nameB, undefined, { sensitivity: 'base' });
    });
}

function bagT(game: GameRuntime, key: string, fallback: string, vars: Record<string, unknown> = {}): string {
    return uiText(key, fallback, vars, game);
}

export function buildEvolutionItemBagTooltipDescription(
    game: GameRuntime,
    itemKey: string,
    baseDescription: string,
): string {
    if (!isEvolutionInventoryItem(itemKey)) return baseDescription;

    const compatible = getOwnedCompatibleEvolutionsForItem(game, itemKey);
    const arrow = bagT(game, 'bag.evolutionItemTooltipArrow', '→');
    const header = bagT(game, 'bag.evolutionItemTooltipHeader', 'Pokémon compatibles :');

    let section: string;
    if (compatible.length === 0) {
        section = bagT(
            game,
            'bag.evolutionItemTooltipNone',
            'Aucun Pokémon compatible dans votre collection.',
        );
    } else {
        const lines = compatible.map((entry) => {
            const fromName = uiPokemonName(game, entry.creatureName);
            const toName = uiPokemonName(game, entry.evolvesTo);
            let line = `${fromName} ${arrow} ${toName}`;
            if (!entry.levelMet && entry.requiredLevel != null) {
                const levelLabel = bagT(game, 'bag.evolutionItemTooltipLevel', 'niv. {level}', {
                    level: entry.requiredLevel,
                });
                line += ` (${levelLabel})`;
            }
            return `• ${line}`;
        });
        section = `${header}<br>${lines.join('<br>')}`;
    }

    const base = (baseDescription || '').trim();
    return base ? `${base}<br><br>${section}` : section;
}
