<script lang="ts">
  import { bag } from '../../stores/bag.svelte.ts';
  import BagItemCard from './BagItemCard.svelte';

  let snap = $derived(bag.inventory);
  let ui = $derived(bag.ui);

  let searchQuery = $state('');
  let sortMode = $state<'default' | 'name' | 'count'>('default');

  const filterKeys = [
    ['all', 'filterAll'],
    ['berries', 'filterBerries'],
    ['combat', 'filterCombat'],
    ['permanent', 'filterPermanent'],
    ['held', 'filterHeld'],
    ['key', 'filterKey'],
    ['evolution_stones', 'filterEvolutionStones'],
    ['ct', 'filterCt'],
    ['misc', 'filterMisc'],
  ] as const;

  function normalize(s: string): string {
    return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  }

  let displayedCards = $derived.by(() => {
    let list = snap.itemCards;
    const q = normalize(searchQuery.trim());
    if (q) {
      list = list.filter((c) => normalize(c.displayName).includes(q) || normalize(c.itemKey).includes(q));
    }
    if (sortMode === 'name') {
      return [...list].sort((a, b) => a.displayName.localeCompare(b.displayName));
    }
    if (sortMode === 'count') {
      return [...list].sort((a, b) => (b.count || 0) - (a.count || 0));
    }
    return list;
  });
</script>

<div id="itemsContainer">
  <div class="inventory-toolbar">
    <div class="inventory-search-wrap">
      <span class="inventory-search-icon" aria-hidden="true">🔍</span>
      <input
        type="search"
        class="inventory-search-input"
        placeholder="Rechercher un objet..."
        bind:value={searchQuery}
        aria-label="Rechercher un objet"
      />
      {#if searchQuery}
        <button type="button" class="inventory-search-clear" onclick={() => { searchQuery = ''; }}>×</button>
      {/if}
    </div>
    <div class="inventory-sort-group">
      <button
        type="button"
        class="inventory-sort-btn"
        class:is-active={sortMode === 'name'}
        onclick={() => { sortMode = sortMode === 'name' ? 'default' : 'name'; }}
        title="Trier par nom (A-Z)"
      >A-Z</button>
      <button
        type="button"
        class="inventory-sort-btn"
        class:is-active={sortMode === 'count'}
        onclick={() => { sortMode = sortMode === 'count' ? 'default' : 'count'; }}
        title="Trier par quantité"
      >Qté</button>
    </div>
  </div>

  <div class="inventory-filters inventory-filters-scroll">
    {#each filterKeys as [value, labelKey] (value)}
      <button
        type="button"
        class="sort-btn inventory-tab-btn"
        class:active={snap.inventoryFilter === value}
        data-filter={value}
        data-action="setInventoryFilter"
        data-arg={value}
      >{ui[labelKey]}</button>
    {/each}
  </div>

  {#if snap.inventoryEmpty || displayedCards.length === 0}
    <div id="inventory-empty-msg" style="text-align: center; color: #94a3b8; padding: 25px 15px; border: 1px dashed rgba(255,255,255,0.1); border-radius: 8px; font-style: italic; font-size: 12px;">
      {#if searchQuery}
        Aucun objet correspondant à « {searchQuery} »
      {:else}
        {snap.inventoryEmptyMessage || ui.inventoryEmpty}
      {/if}
    </div>
  {:else}
    <div id="inventory-empty-msg" hidden></div>
    <div class="inventory-grid">
      {#each displayedCards as card (card.itemKey)}
        <BagItemCard {card} />
      {/each}
    </div>
  {/if}
</div>
