<script lang="ts">
  import { bag } from '../../stores/bag.svelte.ts';
  import { showGameTooltip, hideGameTooltip } from '../../ui/scheduleTooltipHelpers.ts';

  let sections = $derived(bag.eggSections);

  function showHint(e: MouseEvent | FocusEvent, hint: string): void {
    if (!hint) return;
    showGameTooltip(e, '', hint);
  }
</script>

<div class="balls-container" id="ballsContainer" data-svelte-ui="1">
  {#each sections.eggRows as row (row.rarity)}
    <div
      class="ball-item rarity-{row.rarity} egg-item-{row.rarity} egg-clickable"
      role="button"
      tabindex="0"
      data-rarity={row.rarity}
      data-egg-rarity={row.rarity}
      style:display={row.visible ? 'block' : 'none'}
      title={row.hint}
      onmouseenter={(e) => showHint(e, row.hint)}
      onmouseleave={hideGameTooltip}
      onfocus={(e) => showHint(e, row.hint)}
      onblur={hideGameTooltip}
    >
      <div class="rarity-label {row.rarity}" style="pointer-events: none; margin-bottom:2px; font-size:9px; padding:1px 4px;">
        {row.label}
      </div>
      <img src={row.eggSpriteUrl} class="egg-sprite {row.filterClass}" alt={row.alt} />
      <div class="egg-count-label">x{row.countText}</div>
    </div>
  {/each}
  <div class="empty-eggs-message" style:display={sections.showEmptyMessage ? 'block' : 'none'}>
    <img src="img/common-egg.png" class="empty-eggs-message-icon" alt="" />
    <div class="egg-empty-title">{sections.emptyTitle}</div>
    <div class="egg-empty-hint">{sections.emptyHint}</div>
  </div>
</div>
